482→// IsCheckpointsV2Enabled checks if checkpoints v2 (dual-write to refs/entire/) is enabled.
483→// Returns false by default if the key is missing or not a bool.
484→func (s *EntireSettings) IsCheckpointsV2Enabled() bool {
485→	if s.StrategyOptions == nil {
486→		return false
487→	}
488→	val, ok := s.StrategyOptions["checkpoints_v2"].(bool)
489→	return ok && val
490→}
491→
492→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
493→// Returns true if push_sessions is explicitly set to false.
494→func (s *EntireSettings) IsPushSessionsDisabled() bool {
495→	if s.StrategyOptions == nil {
496→		return false
497→	}
498→	val, exists := s.StrategyOptions["push_sessions"]
499→	if !exists {
500→		return false
501→	}
502→	if boolVal, ok := val.(bool); ok {
503→		return !boolVal // disabled = !push_sessions
504→	}
505→	return false
506→}
