373→// FetchMetadataBranch fetches the entire/checkpoints/v1 branch from origin and creates/updates the local branch.
374→// This is used when the metadata branch exists on remote but not locally.
375→// Uses git CLI instead of go-git for fetch because go-git doesn't use credential helpers,
376→// which breaks HTTPS URLs that require authentication.
377→func FetchMetadataBranch(ctx context.Context) error {
378→	branchName := paths.MetadataBranchName
379→
380→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
381→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
382→	defer cancel()
383→
384→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
