377→func FetchMetadataBranch(ctx context.Context) error {
378→	branchName := paths.MetadataBranchName
379→
380→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
381→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
382→	defer cancel()
383→
