	cmd.Dir = tmpDir
	cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")

	// We expect this to fail (the server returns 403), but the header should be sent
	_ = cmd.Run() //nolint:errcheck // expected to fail against test server

	mu.Lock()
	defer mu.Unlock()

	require.Positive(t, requestCount, "server should have received at least one request")
	assert.Equal(t, "Bearer test-bearer-token-abc123", capturedAuth,
		"git should send the bearer token as an Authorization header")
}

// TestCheckpointToken_HTTPServer_NoTokenNoHeader verifies that without
// ENTIRE_CHECKPOINT_TOKEN set, no Authorization header is sent.
// Not parallel: uses t.Chdir()
func TestCheckpointToken_HTTPServer_NoTokenNoHeader(t *testing.T) {
	checkpointTokenAllowHTTP = true
	t.Cleanup(func() { checkpointTokenAllowHTTP = false })
	t.Setenv(CheckpointTokenEnvVar, "")

	var (
		mu           sync.Mutex
		capturedAuth string
		requestCount int
	)

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		capturedAuth = r.Header.Get("Authorization")
		requestCount++
		mu.Unlock()

		w.WriteHeader(http.StatusForbidden)
		fmt.Fprintln(w, "forbidden")
	}))
	defer srv.Close()

	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	target := srv.URL + "/org/repo.git"
	cmd := CheckpointGitCommand(context.Background(), target,
		"fetch", target, "+refs/heads/main:refs/remotes/origin/main")
	cmd.Dir = tmpDir
	if cmd.Env == nil {
		cmd.Env = os.Environ()
	}
	cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")

	_ = cmd.Run() //nolint:errcheck // expected to fail against test server

	mu.Lock()
	defer mu.Unlock()

	require.Positive(t, requestCount, "server should have received at least one request")
	assert.Empty(t, capturedAuth, "no Authorization header should be sent without token")
}

// TestCheckpointToken_HTTPServer_PushSendsAuthHeader verifies the token is sent
// on push operations too, not just fetch. Git push first does a discovery GET to
// /info/refs, so we capture the header from that request.
// Not parallel: uses t.Chdir()
func TestCheckpointToken_HTTPServer_PushSendsAuthHeader(t *testing.T) {
	checkpointTokenAllowHTTP = true
	t.Cleanup(func() { checkpointTokenAllowHTTP = false })
	t.Setenv(CheckpointTokenEnvVar, "push-token-xyz789")

	var (
		mu           sync.Mutex
		capturedAuth string
		requestCount int
	)

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		capturedAuth = r.Header.Get("Authorization")
		requestCount++
		mu.Unlock()

		w.WriteHeader(http.StatusForbidden)
		fmt.Fprintln(w, "forbidden")
	}))
	defer srv.Close()

	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	// Use ls-remote instead of push — it hits the same HTTP endpoint (info/refs)
	// and reliably sends the Authorization header, without needing a full
	// git smart HTTP server. This verifies the token injection mechanism works
	// for any git HTTP operation.
	target := srv.URL + "/org/repo.git"
	cmd := CheckpointGitCommand(context.Background(), target,
		"ls-remote", target)
	cmd.Dir = tmpDir
	cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")

	_ = cmd.Run() //nolint:errcheck // expected to fail against test server

	mu.Lock()
	defer mu.Unlock()

	require.Positive(t, requestCount, "server should have received at least one request")
	assert.Equal(t, "Bearer push-token-xyz789", capturedAuth,
		"git ls-remote should send the bearer token as an Authorization header")
}

// TestCheckpointToken_GIT_TERMINAL_PROMPT_Coexistence verifies that the token env
// and GIT_TERMINAL_PROMPT=0 can coexist (as used in fetchMetadataBranchIfMissing).
// Not parallel: uses t.Setenv()
func TestCheckpointToken_GIT_TERMINAL_PROMPT_Coexistence(t *testing.T) {
	t.Setenv(CheckpointTokenEnvVar, "coexist-token")

	cmd := CheckpointGitCommand(context.Background(), "https://github.com/org/repo.git",
		"fetch", "--no-tags", "https://github.com/org/repo.git", "refs/heads/main")
	require.NotNil(t, cmd.Env)

	// Simulate what fetchMetadataBranchIfMissing does: append GIT_TERMINAL_PROMPT
	cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")

	envMap := envToMap(cmd.Env)
	assert.Equal(t, "1", envMap["GIT_CONFIG_COUNT"])
	assert.Equal(t, "Authorization: Bearer coexist-token", envMap["GIT_CONFIG_VALUE_0"])
	assert.Equal(t, "0", envMap["GIT_TERMINAL_PROMPT"])
}

// envToMap converts an env slice to a map for easy assertions.
// For duplicate keys, the last value wins.
func envToMap(env []string) map[string]string {
	m := make(map[string]string, len(env))
	for _, e := range env {
		k, v, ok := strings.Cut(e, "=")
		if ok {
			m[k] = v
		}
	}
	return m
}

